#include <stdio.h>
#include <stdlib.h>
#define M 100
typedef struct {int in[M],out[M];int ni,no;} Queue;
void enqueue(Queue *q,int x){if(q->ni+q->no==M){fputs("overflow\n",stderr);exit(EXIT_FAILURE);}q->in[q->ni++]=x;}
int dequeue(Queue *q){if(q->no==0)while(q->ni>0)q->out[q->no++]=q->in[--q->ni];if(q->no==0){fputs("underflow\n",stderr);exit(EXIT_FAILURE);}return q->out[--q->no];}
int main(void){Queue q={0};enqueue(&q,10);enqueue(&q,20);printf("%d\n",dequeue(&q));enqueue(&q,30);printf("%d\n",dequeue(&q));printf("%d\n",dequeue(&q));return 0;}
Output: 10,20,30 on separate lines. Stack in receives arrivals, out supplies removals; transfer only when out is empty.

